PRAGMA foreign_keys=ON;
CREATE TABLE sources (source_id TEXT PRIMARY KEY,author TEXT NOT NULL,work TEXT NOT NULL,source_url TEXT NOT NULL,source_version TEXT NOT NULL,retrieved_at TEXT NOT NULL,license TEXT NOT NULL,license_path TEXT NOT NULL);
CREATE TABLE problems (problem_id TEXT PRIMARY KEY,title TEXT NOT NULL,difficulty_level TEXT NOT NULL CHECK(difficulty_level IN ('H1','H2','H3')),difficulty_reason TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(source_id),source_locator_json TEXT NOT NULL,tex_path TEXT NOT NULL UNIQUE,tex_content TEXT NOT NULL,tex_sha256 TEXT NOT NULL,origin_class TEXT NOT NULL CHECK(origin_class IN ('human_authored_native_tex','human_authored_proof_assistant_transcription')),status TEXT NOT NULL CHECK(status='verified_editable_tex'),compile_receipt_path TEXT NOT NULL);
